// ============================================
// VALIDATION INPUT - MCP Language Detector
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- Required context fields ---
const userId = body.user_id || ctx.user_id;
const guildId = body.guild_id || ctx.guild_id;
const userRequest = body.user_request || ctx.user_request;

if (!userId) {
  errors.push('user_id requis');
}
if (!guildId) {
  errors.push('guild_id requis');
}
if (!userRequest) {
  errors.push('user_request requis');
}

// --- Specific webhook parameters ---
const text = body.text || ctx.text;

if (!text) {
  errors.push('text requis');
}

// --- API Keys passed from MCP Server ---
const openaiApiKey = body.openai_api_key || ctx.openai_api_key || body.plugin_context?.api_keys?.openai || '';

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  text: text,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  openaiApiKey: openaiApiKey,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'openai',
    model: 'gpt-4o-mini',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

parameters.jsonBody:
={{ (() => {
  const data = $json;
  const userRequest = data.user_request;
  const textSample = data.text.substring(0, 1000);

  const systemPrompt = `You are a language detection expert. Detect the language of the given text and return a JSON object with:
- code: ISO 639-1 code (e.g., 'en', 'fr', 'es', 'de', 'zh', 'ja', 'ar')
- name: Full language name in English
- confidence: Confidence score 0.0 to 1.0
- script: Writing script (latin, cyrillic, arabic, han, etc.)
- is_mixed: Boolean if multiple languages detected
- languages: Array of detected languages if mixed

User context: "${userRequest}"

Return ONLY valid JSON.`;

  return JSON.stringify({
    model: 'gpt-4o-mini',
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: `Detect the language of this text:\n\n${textSample}` }
    ],
    temperature: 0.1,
    max_tokens: 256
  });
})() }}

