// ============================================
// PARSE LLM RESPONSE - Language Detector
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

// --- Context fields for traceability ---
const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

const statusCode = input.statusCode || 200;

// Initialize trace with llm_response format
const _trace = {
  llm_response: null,
  service_response: null,
  provider: 'openai',
  model: 'gpt-4o-mini',
  tokens: { input: 0, output: 0 },
  latency_ms: 0,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

// Handle API error
if (statusCode >= 400 || input.error) {
  const errorMsg = input.body?.error?.message || input.error?.message || 'OpenAI API error';
  _trace.llm_response = `Error: ${errorMsg}`;
  _trace.service_response = input.body || input;
  _trace.latency_ms = Date.now() - startTime;

  return {
    json: {
      success: false,
      error: {
        code: 'LLM_ERROR',
        message: errorMsg,
        http_status: statusCode
      },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  };
}

// Extract response
const body = input.body || input;
const content = body.choices?.[0]?.message?.content || '{}';
const usage = body.usage || {};

// Populate trace with LLM response
_trace.llm_response = content;
_trace.service_response = body;
_trace.tokens = {
  input: usage.prompt_tokens || 0,
  output: usage.completion_tokens || 0
};

// Parse JSON from response
let detection;
try {
  detection = JSON.parse(content);
} catch (e) {
  _trace.latency_ms = Date.now() - startTime;

  return {
    json: {
      success: false,
      error: {
        code: 'PARSE_ERROR',
        message: 'Failed to parse detection response: ' + e.message,
        http_status: 500
      },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  };
}

_trace.latency_ms = Date.now() - startTime;

return {
  json: {
    success: true,
    data: {
      code: detection.code || 'unknown',
      name: detection.name || 'Unknown',
      confidence: detection.confidence || 0,
      script: detection.script || 'unknown',
      is_mixed: detection.is_mixed || false,
      languages: detection.languages || null,
      text_sample: prevData.text.substring(0, 100) + (prevData.text.length > 100 ? '...' : '')
    },
    meta: {
      provider: 'openai',
      model: 'gpt-4o-mini'
    },
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest,
    _trace: _trace
  }
};

